void backFromHistory(ux::Shell& shell,EffectsCanvas& canvas){canvas.watch=false;CHECK(uitest::tom(shell,ib::tom::HistoryBack));pump(shell,canvas);clear(shell,canvas);auto area=shell.tomPanel()->revealContent();CHECK(area.y0==15);tomReady(shell,canvas);}
void closeTom(ux::Shell& shell,EffectsCanvas& canvas){tomReady(shell,canvas);CHECK(uitest::tom(shell,ib::tom::Close));pump(shell,canvas);until([&]{pump(shell,canvas);return !shell.tomPanel()->active();});clear(shell,canvas);canvas.watch=false;}
input_event event(unsigned short type,unsigned short code,int value){input_event e{};e.type=type;e.code=code;e.value=value;return e;}
// Real Engine/OperationSink route with authored events and a fake display only.
void contact(ux::Shell& shell,EffectsCanvas& canvas,int y){CHECK(shell.writable());spike::Engine engine({{0,1619},{0,2159},1620,2160,0,false},shell.ink(),canvas);spike::FrameAssembler assembler;spike::Scheduler scheduler;spike::SessionStats stats;auto down=std::array{event(EV_KEY,BTN_TOOL_PEN,1),event(EV_ABS,ABS_X,200),event(EV_ABS,ABS_Y,y),event(EV_KEY,BTN_TOUCH,1),event(EV_SYN,SYN_REPORT,0)};canvas.contact=true;CHECK(spike::consumeEvents(down,assembler,engine,scheduler,stats,1,nullptr,&shell));auto count=canvas.submissions;for(int n=0;n<4;++n){CHECK(!shell.tick());canvas.changes();}CHECK(canvas.submissions==count&&canvas.duringContact==0&&!shell.finger(1450,60,false)&&!shell.finger(1100,1960,false));auto move=std::array{event(EV_ABS,ABS_X,400),event(EV_SYN,SYN_REPORT,0)};CHECK(spike::consumeEvents(move,assembler,engine,scheduler,stats,8000001,nullptr,&shell));auto up=std::array{event(EV_KEY,BTN_TOUCH,0),event(EV_SYN,SYN_REPORT,0)};CHECK(spike::consumeEvents(up,assembler,engine,scheduler,stats,16000001,nullptr,&shell));canvas.contact=false;CHECK(stats.contacts==1&&stats.released==1&&engine.flush()==spike::Submit::Accepted);clear(shell,canvas);}
std::pair<int,int> wordPoint(ux::Shell& shell){auto g=shell.semantics().geometry();CHECK(g&&g->available());auto words=g->data["words"].toArray();for(int n=0;n<words.size();++n){auto selected=semantic::select(g,unsigned(n),unsigned(n),1);if(selected->data["normalized"].toString()!="orchard")continue;auto q=selected->data["quads"].toArray()[0].toArray();double x=0,y=0;for(int i=0;i<8;i+=2){x+=q[i].toDouble()/4;y+=q[i+1].toDouble()/4;}auto m=g->data["transform"].toArray();return {int(m[0].toDouble()*x+m[2].toDouble()*y+m[4].toDouble()),int(m[1].toDouble()*x+m[3].toDouble()*y+m[5].toDouble())};}throw std::runtime_error("authored-word-missing");}
void libraryMenu(ux::Shell& shell,EffectsCanvas& canvas,bool effect){if(effect)opening(shell,canvas,true);else{pump(shell,canvas);CHECK(!shell.revealPending()&&canvas.phases==0);idle(shell,canvas);}}
