void tools(ux::Shell& shell,EffectsCanvas& canvas){show(shell,canvas);CHECK(uitest::openTools(shell));canvas.changes();clear(shell,canvas);}
void closeTools(ux::Shell& shell,EffectsCanvas& canvas){auto r=uitest::toolsClose(shell);tap(shell,canvas,(r.x0+r.x1)/2,(r.y0+r.y1)/2);clear(shell,canvas);CHECK(shell.action(ux::Action::Hide));canvas.changes();until([&]{pump(shell,canvas);return !shell.styledInk()->status().busy&&shell.unsaved()==0;});}
